css:
/* BFD Agora for T3. Tokens: agora-platform app/src/styles/brand-tokens.css. State by thin rules and type, never fills. */
:root { --bfd-ink:#171717; --bfd-paper:#FAFAFA; --bfd-line:#D4D4D8; --bfd-muted:#64646D; --bfd-gold:#805B00; --bfd-mint:#0C7243; --bfd-stuck:#B52222; }
.dark { --bfd-ink:#F4F4F5; --bfd-paper:#18181B; --bfd-line:#2E2E33; --bfd-muted:#A1A1AA; --bfd-gold:#FFC800; --bfd-mint:#5AE09A; --bfd-stuck:#FF8787; }
body { counter-reset: bfdneeds bfdstuck bfdlive; }
html, body, button, input, textarea, select, .composer-tiptap, .chat-markdown { font-family: "Montserrat", ui-sans-serif, system-ui, sans-serif !important; }
.chat-markdown h1, .chat-markdown h2, .chat-markdown h3 { font-weight: 700 !important; letter-spacing: 0 !important; }

/* Brand */
a[aria-label="T3 Code home"] > * { display: none !important; }
a[aria-label="T3 Code home"] { display: inline-flex !important; align-items: center !important; gap: 0 !important; }
a[aria-label="T3 Code home"]::before { content: ""; display: inline-block; width: 39px; height: 13px; background: var(--bfd-ink); -webkit-mask: url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 2097 700'%3E%3Cg fill='%23F4F4F5'%3E%3Cpath transform='translate(-57,700) scale(1,-1)' d='M747 193Q747 101 671.0 50.5Q595 0 451 0H57V700H431Q571 700 642.5 650.0Q714 600 714 517Q714 468 689.5 429.0Q665 390 617 366Q679 343 713.0 299.0Q747 255 747 193ZM289 535V431H399Q476 431 476 483Q476 535 399 535ZM509 220Q509 275 431 275H289V165H431Q509 165 509 220Z'/%3E%3Cpath transform='translate(686,700) scale(1,-1)' d='M293 522V402H585V224H293V0H57V700H626V522Z'/%3E%3Cpath transform='translate(1300,700) scale(1,-1)' d='M57 700H402Q519 700 608.5 657.5Q698 615 747.5 536.0Q797 457 797 350Q797 243 747.5 164.0Q698 85 608.5 42.5Q519 0 402 0H57ZM392 184Q468 184 513.5 227.5Q559 271 559 350Q559 429 513.5 472.5Q468 516 392 516H293V184Z'/%3E%3C/g%3E%3C/svg%3E ") no-repeat left center / contain; mask: url("data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 2097 700'%3E%3Cg fill='%23F4F4F5'%3E%3Cpath transform='translate(-57,700) scale(1,-1)' d='M747 193Q747 101 671.0 50.5Q595 0 451 0H57V700H431Q571 700 642.5 650.0Q714 600 714 517Q714 468 689.5 429.0Q665 390 617 366Q679 343 713.0 299.0Q747 255 747 193ZM289 535V431H399Q476 431 476 483Q476 535 399 535ZM509 220Q509 275 431 275H289V165H431Q509 165 509 220Z'/%3E%3Cpath transform='translate(686,700) scale(1,-1)' d='M293 522V402H585V224H293V0H57V700H626V522Z'/%3E%3Cpath transform='translate(1300,700) scale(1,-1)' d='M57 700H402Q519 700 608.5 657.5Q698 615 747.5 536.0Q797 457 797 350Q797 243 747.5 164.0Q698 85 608.5 42.5Q519 0 402 0H57ZM392 184Q468 184 513.5 227.5Q559 271 559 350Q559 429 513.5 472.5Q468 516 392 516H293V184Z'/%3E%3C/g%3E%3C/svg%3E ") no-repeat left center / contain; flex-shrink: 0; }
a[aria-label="T3 Code home"]::after { content: "Agora"; margin-left: 12px; padding-left: 12px; border-left: 1px solid var(--bfd-line); font: 400 12px/13px "JetBrains Mono", ui-monospace, "SF Mono", Menlo, monospace; letter-spacing: 0; color: var(--bfd-muted); white-space: nowrap; }

/* Surfaces */
[data-user-message-bubble] { border: 1px solid var(--bfd-line) !important; border-radius: 12px !important; }
[data-slot="composer-host"] { border-radius: 12px !important; border: 1px solid var(--bfd-line) !important; }
[data-slot="composer-host"]:focus-within { border-color: var(--bfd-muted) !important; }
[data-thread-details-card] { border: 1px solid var(--bfd-line) !important; border-radius: 12px !important; }
[data-chat-header] { border-bottom: 1px solid var(--bfd-line) !important; }
[data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"] { border-radius: 12px !important; border: 1px solid var(--bfd-line) !important; }
[data-slot="tooltip-popup"] { border-radius: 6px !important; font-weight: 500; }
[data-slot="button"] { border-radius: 8px; }
[data-slot="project-monogram"] svg { filter: grayscale(1) contrast(1.15); }
.chat-markdown-codeblock { border: 1px solid var(--bfd-line) !important; border-radius: 8px !important; }
svg.lucide { stroke-width: 1.75; }
::-webkit-scrollbar-thumb { background: var(--bfd-line); border-radius: 8px; }

/* Sidebar, after Agora's AdminSidebar: quiet rows, paper card and gold inset rule for attention, state as a thin inset rule */
[data-slot="sidebar"] li:has([data-testid$="-shelf-toggle"]), [data-slot="sidebar"] :has(> [data-testid$="-shelf-toggle"]) { margin-top: 16px !important; padding-top: 10px; border-top: 1px solid var(--bfd-line); }
[data-thread-item] [data-sidebar-row] { border-radius: 6px !important; border: 1px solid transparent; }
[data-thread-item] [data-sidebar-row]:is([aria-current="page"],[aria-current="true"]) { border-color: var(--bfd-line) !important; background-color: var(--bfd-paper) !important; }
[data-thread-item]:has([data-sidebar-row]:is([aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"])) { content-visibility: visible !important; counter-increment: bfdlive; }
[data-thread-item] [data-sidebar-row]:is([aria-label*=", Working"],[aria-label*=", Goal"],[aria-label*=", Setting up"],[aria-label*=", Waiting"]) { background-image: linear-gradient(var(--bfd-mint),var(--bfd-mint)) !important; background-size: 2px calc(100% - 16px) !important; background-position: left center !important; background-repeat: no-repeat !important; }
[data-thread-item]:has([data-sidebar-row]:is([aria-label*=", Failed"],[aria-label*=", Limited"])) { content-visibility: visible !important; counter-increment: bfdstuck; }
[data-thread-item] [data-sidebar-row]:is([aria-label*=", Failed"],[aria-label*=", Limited"]) { background-image: linear-gradient(var(--bfd-stuck),var(--bfd-stuck)) !important; background-size: 2px calc(100% - 16px) !important; background-position: left center !important; background-repeat: no-repeat !important; }
[data-thread-item]:has([data-sidebar-row]:is([aria-label^="NEEDS " i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"])) { content-visibility: visible !important; counter-increment: bfdneeds; }
[data-thread-item] [data-sidebar-row]:is([aria-label^="NEEDS " i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"]) { background-color: var(--bfd-paper) !important; border-color: var(--bfd-line) !important; background-image: linear-gradient(var(--bfd-gold),var(--bfd-gold)) !important; background-size: 2px calc(100% - 16px) !important; background-position: left center !important; background-repeat: no-repeat !important; }
li[data-thread-item]:nth-child(1 of :has([data-sidebar-row]:is([aria-label^="NEEDS " i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"])))::before { content: "Needs you"; display: block; padding: 6px 12px 6px; font: 500 12px/16px "Montserrat", sans-serif; color: var(--bfd-muted); }

/* Header summary: plain text, as Agora shows status */
[data-chat-header]::before { content: "All clear"; order: -1; flex-shrink: 0; margin-right: 12px; font: 500 12px/20px "Montserrat", sans-serif; color: var(--bfd-muted); white-space: nowrap; }
body:has([data-sidebar-row]:is([aria-label^="NEEDS " i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"])) [data-chat-header]::before { content: counter(bfdneeds) " need you"; font-weight: 600; color: var(--bfd-gold); }
[data-chat-header]::after { content: counter(bfdlive) " working"; order: -1; flex-shrink: 0; margin-right: 14px; padding-right: 14px; border-right: 1px solid var(--bfd-line); font: 500 12px/20px "Montserrat", sans-serif; color: var(--bfd-muted); white-space: pre; }
body:has([data-sidebar-row]:is([aria-label*=", Failed"],[aria-label*=", Limited"])) [data-chat-header]::after { content: counter(bfdstuck) " stuck  \00B7  " counter(bfdlive) " working"; }
/* Motion and touch: short, eased, never looping */
:root { --bfd-ease: cubic-bezier(.2,.7,.2,1); }
[data-thread-item] [data-sidebar-row] { transition: background-color .16s var(--bfd-ease), border-color .16s var(--bfd-ease), background-size .22s var(--bfd-ease); }
[data-thread-item] [data-sidebar-row]:hover { background-color: color-mix(in srgb, var(--bfd-ink) 6%, transparent) !important; }
[data-thread-item] [data-sidebar-row]:is([aria-label^="NEEDS " i],[aria-label*=", Approval"],[aria-label*=", Input"],[aria-label*=", Request"]):hover { background-color: color-mix(in srgb, var(--bfd-ink) 4%, var(--bfd-paper)) !important; border-color: color-mix(in srgb, var(--bfd-gold) 45%, var(--bfd-line)) !important; }
[data-thread-item] [data-sidebar-row]:is([aria-label^="NEEDS " i],[aria-label*=", "]):hover { background-size: 2px calc(100% - 8px) !important; }
[data-thread-item] [data-sidebar-row]:active { transform: scale(.992); transition-duration: .06s; }
[data-thread-item] [data-sidebar-row]:focus-visible { outline: 2px solid var(--bfd-gold) !important; outline-offset: -2px; }
[data-slot="button"], [data-toolbar-control], [data-slot="sidebar-menu-button"] { transition: background-color .14s var(--bfd-ease), color .14s var(--bfd-ease), border-color .14s var(--bfd-ease), transform .08s var(--bfd-ease); }
[data-slot="button"]:active { transform: scale(.97); }
[data-slot="composer-host"] { transition: border-color .18s var(--bfd-ease), box-shadow .18s var(--bfd-ease); }
[data-slot="composer-host"]:focus-within { box-shadow: 0 0 0 3px color-mix(in srgb, var(--bfd-ink) 7%, transparent); }
[data-testid$="-shelf-toggle"] { font-weight: 500 !important; color: var(--bfd-muted) !important; transition: color .14s var(--bfd-ease); }
[data-testid$="-shelf-toggle"]:hover { color: var(--bfd-ink) !important; }
[data-chat-header]::before, [data-chat-header]::after { font-variant-numeric: tabular-nums; }
::selection { background: color-mix(in srgb, var(--bfd-gold) 32%, transparent); }
@media (prefers-reduced-motion: reduce) { [data-thread-item] [data-sidebar-row], [data-slot="button"], [data-thread-item] [data-sidebar-row]::after { transition: none !important; } }
